use super::{ctx,update_field,Edit};
use crate::{photography,section_model::{self,Section,Sections,FIELD,MAX_SECTIONS,OPTIONS},studio_model::Media};
use leptos::prelude::*;

fn document(state:&Edit)->Sections {section_model::parse(&state.get_untracked().draft.field(FIELD)).unwrap_or_default()}
fn save(state:&Edit,doc:&Sections,user:u64){update_field(state,FIELD,serde_json::to_string(doc).unwrap(),user);}
fn change(state:&Edit,id:u32,user:u64,edit:impl FnOnce(&mut Section)) {
    let mut doc=document(state);if let Some(section)=doc.sections.iter_mut().find(|s|s.id==id){edit(section);save(state,&doc,user);}
}
fn current(state:&Edit,id:u32)->Section {section_model::parse(&state.get().draft.field(FIELD)).unwrap_or_default().sections.into_iter().find(|s|s.id==id).unwrap_or_else(||Section::new(id,"text"))}

#[component]
pub(super) fn PageSectionEditor(state:Edit,media:Vec<Media>)->impl IntoView {
    let user=ctx().session.get_value().user.id;let state=StoredValue::new(state);let media=StoredValue::new(media);
    let removed=RwSignal::new(None::<(usize,Section)>);let notice=RwSignal::new(String::new());
    let doc=move||section_model::parse(&state.get_value().get().draft.field(FIELD));
    view!{<section class="editor-panel section-composer" id="page-sections"><div class="composer-heading"><span class="eyebrow">"YOUR WORDS. A CONSISTENT DESIGN."</span><h2>"Page sections"</h2><p class="small-note">"Build with approved layouts. These sections follow the page’s standard content, before the footer. Typography, colours and spacing are taken care of."</p></div>
        {move||doc().err().map(|e|view!{<p role="alert" class="notice error">{e}</p>})}
        <div class="section-patterns" role="group" aria-label="Add an approved section">{OPTIONS.iter().map(|(kind,label,description)|view!{<button type="button" class="section-pattern" disabled=move||doc().is_err()||doc().is_ok_and(|d|d.sections.len()>=MAX_SECTIONS) on:click=move|_|{let mut d=document(&state.get_value());if d.sections.len()>=MAX_SECTIONS{return;}let max=d.sections.iter().map(|s|s.id).chain(removed.get_untracked().map(|(_,s)|s.id)).max().unwrap_or(0);d.sections.push(Section::new(max.saturating_add(1),kind));save(&state.get_value(),&d,user);notice.set(format!("Added {label}. Fill in the section below."));}><span class=format!("pattern-sketch sketch-{kind}") aria-hidden="true"><i/><b/><em/></span><strong>{*label}</strong><small>{*description}</small><span>"Add section +"</span></button>}).collect_view()}</div>
        <p class="small-note">{move||format!("{} of {MAX_SECTIONS} sections · Use Move up or Move down to change their order.",doc().map(|d|d.sections.len()).unwrap_or(0))}</p><p class="composer-notice" role="status">{notice}</p>
        <Show when=move||removed.get().is_some()><button class="text-button" type="button" disabled=move||doc().is_ok_and(|d|d.sections.len()>=MAX_SECTIONS) on:click=move|_|{if let Some((index,mut s))=removed.get_untracked(){let mut d=document(&state.get_value());if d.sections.len()>=MAX_SECTIONS{return;}if d.sections.iter().any(|v|v.id==s.id){s.id=d.sections.iter().map(|v|v.id).max().unwrap_or(0)+1;}let at=index.min(d.sections.len());d.sections.insert(at,s);save(&state.get_value(),&d,user);removed.set(None);notice.set("Section restored.".into());}}>"Undo last removal"</button></Show>
        <div class="section-editors"><For each=move||doc().unwrap_or_default().sections key=|s|s.id children=move|section|{let id=section.id;view!{<SectionEditor state=state.get_value() id media=media.get_value() on_action=Callback::new(move|action:&'static str|{let mut d=document(&state.get_value());let Some(index)=d.sections.iter().position(|s|s.id==id)else{return;};match action{"up" if index>0=>{d.sections.swap(index,index-1);notice.set("Section moved up.".into());},"down" if index+1<d.sections.len()=>{d.sections.swap(index,index+1);notice.set("Section moved down.".into());},"remove"=>{removed.set(Some((index,d.sections.remove(index))));notice.set("Section removed. You can undo this change.".into());},_=>return}save(&state.get_value(),&d,user);})/>}}/></div>
        <Show when=move||doc().is_ok_and(|d|d.sections.is_empty())><div class="section-empty"><strong>"Start with the story you want to tell."</strong><p>"Choose a layout above. Nothing is added to the public page until you publish."</p></div></Show>
    </section>}
}

#[component]
fn SectionField(state:Edit,id:u32,key:&'static str,label:&'static str,#[prop(default=false)] multiline:bool,#[prop(default=160)] max:usize)->impl IntoView {
    let state=StoredValue::new(state);let user=ctx().session.get_value().user.id;let field_id=format!("section-{id}-{key}");
    let value=move||{let s=current(&state.get_value(),id);match key{"title"=>s.title,"eyebrow"=>s.eyebrow,"body"=>s.body,"alt"=>s.alt,"caption"=>s.caption,"credit"=>s.credit,"source_url"=>s.source_url,"image"=>s.image,"button_text"=>s.button_text,_=>s.button_url}};
    let set=move|v:String|change(&state.get_value(),id,user,|s|match key{"title"=>s.title=v,"eyebrow"=>s.eyebrow=v,"body"=>s.body=v,"alt"=>s.alt=v,"caption"=>s.caption=v,"credit"=>s.credit=v,"source_url"=>s.source_url=v,"image"=>s.image=v,"button_text"=>s.button_text=v,_=>s.button_url=v});
    view!{<div class="field"><label for=field_id.clone()>{label}</label>{if multiline{view!{<textarea id=field_id rows=if key=="body"{5}else{3} maxlength=max prop:value=value on:input=move|e|set(event_target_value(&e))/>}.into_any()}else{view!{<input id=field_id maxlength=max prop:value=value on:input=move|e|set(event_target_value(&e))/>}.into_any()}}</div>}
}

#[component]
fn SectionEditor(state:Edit,id:u32,media:Vec<Media>,on_action:Callback<&'static str>)->impl IntoView {
    let initial=current(&state,id);let photo=initial.has_photo();let kind=initial.kind.clone();let title=initial.label();let state=StoredValue::new(state);let user=ctx().session.get_value().user.id;
    let read=move||current(&state.get_value(),id);let index=move||section_model::parse(&state.get_value().get().draft.field(FIELD)).unwrap_or_default().sections.iter().position(|s|s.id==id).unwrap_or(0);
    let count=move||section_model::parse(&state.get_value().get().draft.field(FIELD)).unwrap_or_default().sections.len();
    view!{<details class="section-editor" data-section-id=id open=initial.title.is_empty()><summary><span class="section-order">{move||format!("{:02}",index()+1)}</span><span><strong>{move||{let s=read();if s.title.is_empty(){title.to_string()}else{s.title}}}</strong><small>{title}{move||if read().hidden{" · Hidden from the page"}else{" · Included on the page"}}</small></span><span aria-hidden="true">"+"</span></summary><div class="section-editor-body"><div class="section-order-actions"><button class="button" type="button" disabled=move||index()==0 on:click=move|_|on_action.run("up")>"Move up"</button><button class="button" type="button" disabled=move||{index()+1>=count()} on:click=move|_|on_action.run("down")>"Move down"</button><button class="text-button" type="button" on:click=move|_|on_action.run("remove")>"Remove section"</button></div><label class="section-visibility"><input type="checkbox" prop:checked=move||!read().hidden on:change=move|e|{let shown=event_target_checked(&e);change(&state.get_value(),id,user,|s|s.hidden=!shown);}/><span>"Include this section on the page"</span></label>
        {(kind!="photo").then(||view!{<SectionField state=state.get_value() id key="eyebrow" label="Section label (optional)" max=80/><SectionField state=state.get_value() id key="title" label="Section heading"/><SectionField state=state.get_value() id key="body" label="Section text" multiline=true max=5000/>})}
        {photo.then(||view!{<div class="section-photo-controls"><label class="field"><span>"Section photograph"</span><select aria-label="Section photograph" prop:value=move||read().image on:change=move|e|{let file=event_target_value(&e);change(&state.get_value(),id,user,|s|{s.x=50;s.y=50;if let Some(p)=photography::by_file(&file){s.image=p.file;s.alt=p.alt;s.caption=p.caption;s.credit=p.credit;s.source_url=format!("/credits#photo-{}",p.name);}else{s.image=file;s.alt.clear();s.caption.clear();s.credit.clear();s.source_url.clear();}});} ><option value="">"Choose a photograph"</option>{photography::CATEGORIES.iter().map(|category|view!{<optgroup label=*category>{photography::collection().iter().filter(|p|p.category==*category).map(|p|view!{<option value=p.file.clone()>{p.caption.clone()}</option>}).collect_view()}</optgroup>}).collect_view()}<optgroup label="Uploaded photographs">{media.into_iter().filter(|m|m.mime.starts_with("image/")).map(|m|view!{<option value=m.url>{m.name}</option>}).collect_view()}</optgroup></select></label><p class="small-note">"Collection photographs bring their captions, descriptions and credits with them. Keep historical context with the image."</p>
        <Show when=move||!read().image.is_empty()><div class="section-focus-checks">{[("Landscape",false),("Portrait",true)].into_iter().map(|(label,portrait)|view!{<figure class:portrait=portrait><img src=move||read().image alt="" loading="lazy" style=move||format!("object-position:{}% {}%",read().x,read().y)/><figcaption>{label}" focus check"</figcaption></figure>}).collect_view()}</div></Show>
        {[ ("x","Section horizontal focus"),("y","Section vertical focus") ].into_iter().map(|(axis,label)|view!{<label class="field section-focus"><span>{label}<span class="focus-value" aria-hidden="true">{move||format!("{}%",if axis=="x"{read().x}else{read().y})}</span></span><input type="range" min="0" max="100" step="1" prop:value=move||if axis=="x"{read().x}else{read().y}.to_string() on:input=move|e|{let value=event_target_value(&e).parse::<u8>().unwrap_or(50).min(100);change(&state.get_value(),id,user,|s|if axis=="x"{s.x=value}else{s.y=value});}/></label>}).collect_view()}
        <SectionField state=state.get_value() id key="alt" label="Section photo alt text" max=500/><p class="small-note">"Describe the important visual information. The caption supplies place, date and context."</p><SectionField state=state.get_value() id key="caption" label="Section photo caption" multiline=true max=600/><SectionField state=state.get_value() id key="credit" label="Section photo credit" max=240/>
        <details class="section-image-address"><summary>"Photo address & source"</summary><SectionField state=state.get_value() id key="image" label="Section photo address" max=2048/><SectionField state=state.get_value() id key="source_url" label="Section photo source or license" max=2048/></details></div>})}
        {(kind=="split").then(||view!{<label class="field"><span>"Photo placement"</span><select aria-label="Photo placement" prop:value=move||if read().reverse{"right"}else{"left"} on:change=move|e|{let right=event_target_value(&e)=="right";change(&state.get_value(),id,user,|s|s.reverse=right);} ><option value="left">"Photo on the left"</option><option value="right">"Photo on the right"</option></select><small>"On phones the photograph comes first."</small></label>})}
        {(kind!="photo").then(||view!{<SectionField state=state.get_value() id key="button_text" label="Section button text" max=100/><SectionField state=state.get_value() id key="button_url" label="Section button destination" max=2048/><p class="small-note">"Use an HTTPS address or a page address such as /get-involved. Buttons are optional except in an Invitation."</p>})}
        {move||{let issues=section_model::issues(&Sections{version:1,sections:vec![read()]});(!issues.is_empty()).then(||view!{<div class="section-needed"><strong>"Before publishing"</strong><ul>{issues.into_iter().map(|issue|view!{<li>{issue.split_once(": ").map(|(_,v)|v.to_owned()).unwrap_or(issue)}</li>}).collect_view()}</ul></div>})}}
        </div></details>}
}

#[component]
pub(super) fn PublishingChecks(state:Edit)->impl IntoView {
    let state=StoredValue::new(state);
    view!{<section class="editor-panel publishing-checks"><h2>"Content checks"</h2>{move||{let issues=section_model::publishing_issues(&state.get_value().get().draft);if issues.is_empty(){view!{<p class="checks-ready">"Required content is in place."</p><p class="small-note">"Preview the page, check the facts and links, then publish when ready."</p>}.into_any()}else{view!{<p class="small-note">"Your draft can be saved. Complete these details before publishing."</p><ul>{issues.into_iter().map(|s|view!{<li>{s}</li>}).collect_view()}</ul>}.into_any()}}}</section>}
}

#[component]
pub(super) fn ResponsivePreview(source:Signal<String>,on_close:Callback<()>)->impl IntoView {
    let node=NodeRef::<leptos::html::Dialog>::new();let width=RwSignal::new(0u32);
    Effect::new(move |_|{#[cfg(feature="hydrate")]if let Some(dialog)=node.get(){let _=dialog.show_modal();}});
    view!{<dialog node_ref=node class="studio-dialog preview-dialog responsive-preview" aria-labelledby="preview-title" on:cancel=move|event:leptos::ev::Event|{event.prevent_default();on_close.run(());}>
        <div class="preview-toolbar"><div><h2 id="preview-title">"Private preview"</h2><p>"Your saved draft, in the website’s actual layout."</p></div><a class="button" href=source target="_blank" rel="noopener">"Open full preview ↗"</a><button class="button" on:click=move|_|on_close.run(())>"Close preview"</button></div>
        <div class="preview-sizebar"><div role="group" aria-label="Preview size">{[(0,"Fit window"),(1280,"Desktop"),(768,"Tablet"),(390,"Phone")].into_iter().map(|(size,label)|view!{<button class:active=move||width.get()==size aria-pressed=move||(width.get()==size).to_string() on:click=move|_|width.set(size)>{label}</button>}).collect_view()}</div><p role="status">{move||if width.get()==0{"Fits your window".to_string()}else{format!("{} px wide · Scroll sideways on smaller screens",width.get())}}</p></div>
        <div class="preview-stage"><iframe title="Website draft preview" src=source style=move||if width.get()==0{"width:100%".to_string()}else{format!("width:{}px",width.get())}/></div>
    </dialog>}
}
